
.role-assign-mask {
  position: fixed;
  inset: 0;
  z-index: 2700;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 18px;
  background: color-mix(in srgb, black 48%, transparent);
  backdrop-filter: blur(6px);
}

.role-assign-picker {
  display: grid;
  gap: 14px;
  width: min(100%, 420px);
  max-height: min(90vh, 640px);
  padding: 18px;
  background: color-mix(in srgb, var(--surface) 92%, black 8%);
  border: 1px solid var(--demo-border-accent-soft);
  box-shadow: var(--demo-shadow-card);
}

.role-assign-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.role-assign-head strong {
  display: block;
  font-size: 16px;
}

.role-assign-close {
  min-height: 32px;
  padding: 0 10px;
  border: 1px solid color-mix(in srgb, var(--primary) 22%, transparent);
  background: color-mix(in srgb, var(--surface) 20%, transparent);
  color: inherit;
  cursor: pointer;
}

.role-assign-preview {
  display: flex;
  gap: 12px;
  padding: 10px;
  border: 1px solid color-mix(in srgb, var(--primary) 18%, transparent);
  background: color-mix(in srgb, var(--surface) 16%, transparent);

  img {
    width: 68px;
    height: 90px;
    object-fit: cover;
    border-radius: 8px;
  }
}

.role-assign-preview-copy {
  display: flex;
  flex-direction: column;
  gap: 4px;
  min-width: 0;
  max-width: 100%;
  color: var(--demo-text-secondary);
  font-size: 12px;
}

.role-assign-preview-copy small {
  display: block;
  max-width: 100%;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.role-assign-search {
  display: grid;
  gap: 6px;
}

.role-assign-search span {
  font-size: 11px;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--demo-text-muted);
}

.role-assign-search input {
  width: 100%;
  padding: 10px 12px;
  border: 1px solid color-mix(in srgb, var(--primary) 18%, transparent);
  border-radius: 12px;
  background: color-mix(in srgb, var(--surface) 20%, transparent);
  color: inherit;
}

.role-assign-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px;
  max-height: 320px;
  overflow: auto;
  padding-right: 4px;
}

.role-assign-option {
  display: grid;
  gap: 4px;
  padding: 10px;
  border: 1px solid color-mix(in srgb, var(--primary) 16%, transparent);
  background: color-mix(in srgb, var(--surface) 18%, transparent);
  color: inherit;
  cursor: pointer;
  text-align: left;
  transition:
    transform 160ms ease,
    border-color 160ms ease,
    background 160ms ease;
}

.role-assign-option:hover {
  border-color: color-mix(in srgb, var(--primary) 38%, transparent);
  background: color-mix(in srgb, var(--primary) 8%, transparent);
  transform: translateY(-1px);
}

.role-assign-option.owned {
  border-color: color-mix(in srgb, var(--primary) 48%, transparent);
  background: color-mix(in srgb, var(--primary) 14%, transparent);
}

.role-assign-option small {
  color: var(--demo-text-muted);
}

.role-assign-empty {
  padding: 16px;
  border: 1px dashed color-mix(in srgb, var(--primary) 22%, transparent);
  color: var(--demo-text-muted);
  text-align: center;
}

@media (max-width: 640px) {
  .role-assign-grid {
    grid-template-columns: minmax(0, 1fr);
  }
}
